# craft output with 7 and 6 line extensions from both ends
G=[[4]*11 for _ in range(26)]
for r,c,v in [(4,7,7),(5,8,7),(5,9,8),(6,8,6),(6,9,8),(7,7,6),(7,10,8)]:G[r][c]=v
# rays all from matching diagonal neighboring pairs, outwards each endpoint
for color,dr,dc,points in [(7,1,1,[(4,7),(5,8)]),(6,1,-1,[(6,8),(7,7)])]:
 for r,c in points:
  for sign in [-1,1]:
   rr,cc=r+sign*dr,c+sign*dc
   while 0<=rr<26 and 0<=cc<11 and G[rr][cc]==4:
    G[rr][cc]=color;rr+=sign*dr;cc+=sign*dc
print(G)
